    const arrayCommandEvent = JSON.stringify({
      ts: Date.now(), seq: 1, type: 'session.update', session_id: sessionId,
      data: { update: { sessionUpdate: 'tool_call', rawInput: { command: ['/usr/bin/bash', '-lc', 'kspec task complete @my-task'] } } },
